edges = []
for i in range(15):
    for j in range(1, 4):
        u = i
        v = (i + j) % 15
        if u < v:
            edges.append((u, v))
        else:
            edges.append((v, u))
edges = list(set(edges))
edges.sort()
flat_edges = []
for u, v in edges:
    flat_edges.extend([u, v])
print(flat_edges)
